/**
 * Analyze - historical reporting over one date range (the Engage
 * AnalyticsView), rebuilt on the Horizon kit and the NetSapiens v2 statistics
 * endpoints.
 *
 * Engage reads the v1 `queue_details` dialect, which Horizon apps cannot reach
 * (v1 is not proxied). The v2 statistics endpoints are, and they answer on
 * the lab, so the figures here are the switch's own:
 *
 *   Queue performance   statistics/callqueues/per-queue (+ aggregate for the domain service level)
 *   Agent performance   statistics/agent
 *   Abandoned calls     callqueuereport/abandoned
 *   Dialed numbers      statistics/dnis
 *   Call history        CDRs (panels/CallHistorySection, with its own range)
 *
 * One read of the four reports serves every tab, so switching tabs costs
 * nothing and the tabs describe the same instant. It re-reads every 60 s
 * while a report tab is showing and the page is visible (five requests a
 * minute against the proxy's 100), and when the range changes.
 *
 * A failed read shows the failure, never zeros: a reports screen reading
 * "0 offered" against a read that failed looks like a quiet day.
 */
import type * as React from 'react';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { ChartSeries, DatagridColumn, DatagridToolbarConfig } from '@netsapiens/flow-sdk';

