/**
 * Virtual Switchboard - the app's full-page route (/apps/switchboard).
 *
 * The Engage switchboard's shell, rebuilt on the Horizon kit:
 *   header      one row (ui/CompactPage): title and domain, the modes Real-Time (1) /
 *               Operate (2) / Analyze (3) / Wallboard (4) gated by scope, the KPI
 *               strip (Waiting, Longest, Available, On call), Live indicator, user
 *               badge, the operator's status switcher, the domain picker
 *   body        the selected mode; Real-Time and Operate carry the operator rail
 *
 * Data comes from one shared poller (data/SwitchboardData.tsx); clicks run
 * through data/actions.tsx and report back as toasts.
 */
import type * as React from 'react';
import { useCallback, useEffect, useMemo } from 'react';
import { useFlowContext } from '@netsapiens/flow-sdk';

import type { ZoneMarkerProps } from '../App';
import type { Operator } from '../types';
import { SwitchboardDataProvider, useSwitchboard } from '../data/SwitchboardData';
import { ActionsProvider, useActions } from '../data/actions';
import { PanelHost, PanelsProvider, usePanels } from '../data/panels';
import { usePersistentState, oneOf } from '../data/persist';
import { DomainPicker, useDomainChoice } from '../data/domainChoice';
import { takeHandoff } from '../data/handoff';
import { useNow } from '../data/clock';
import * as ns from '../api/ns';
import { capabilitiesFor } from '../model/capabilities';
import { DEFAULT_STATUS_OPTIONS, resolveCurrentStatus, statusTone } from '../model/agents';
import { deriveKpis, waitBand } from '../model/queues';
import { formatAgo, formatMinSec } from '../model/format';
import { agentId } from '../model/agents';
import { useKit } from '../ui/kit';
import { CompactPage } from '../ui/CompactPage';
import { ActionToasts, toneText } from '../ui/bits';
import type { Tone } from '../ui/bits';
import { RealTimeView } from '../views/realtime/RealTimeView';
import { OperateView } from '../views/operate/OperateView';
import { AnalyzeView } from '../views/analyze/AnalyzeView';
import { WallboardView } from '../views/wallboard/WallboardView';
import { OperatorRail } from '../views/rail/OperatorRail';

export type Mode = 'board' | 'operate' | 'analyze' | 'wallboard';

const MODES: Array<{ value: Mode; label: string; icon: string; key: string }> = [
  { value: 'board', label: 'Real-Time', icon: 'lucide:layout-grid', key: '1' },
  { value: 'operate', label: 'Operate', icon: 'lucide:headset', key: '2' },
  { value: 'analyze', label: 'Analyze', icon: 'lucide:chart-column', key: '3' },
  { value: 'wallboard', label: 'Wallboard', icon: 'lucide:monitor', key: '4' },
];

export default function SwitchboardPage(marker: ZoneMarkerProps) {
  const { api, user } = useFlowContext();
  const caps = useMemo(() => capabilitiesFor(user.scope), [user.scope]);
  // Shared with Call Flow: a domain picked on one page carries to the other.
  const { domain, multiDomain, pick } = useDomainChoice();

  const operator = useMemo<Operator>(
    () => ({
      ext: user.extension ?? '',
      domain: user.domain,
      displayName: user.displayName,
      scope: user.scope ?? '',
      site: user.site ?? '',
      department: user.department ?? '',
    }),
    [user.department, user.displayName, user.domain, user.extension, user.scope, user.site],
  );

  return (
    <ActionsProvider>
      <SwitchboardDataProvider api={api} domain={domain} operator={operator} caps={caps}>
        <PanelsProvider>
          <Shell marker={marker} multiDomain={multiDomain} onPickDomain={pick} />
          <PanelHost />
          <HandoffReceiver />
        </PanelsProvider>
        <ActionToasts />
      </SwitchboardDataProvider>
    </ActionsProvider>
  );
}

function Shell({
  marker,
  multiDomain,
  onPickDomain,
}: {
  marker: ZoneMarkerProps;
  multiDomain: boolean;
  onPickDomain: (d: string) => void;
}) {
  const kit = useKit();
  const { Box, Stack, Tabs, Typography, Alert } = kit;
  const sb = useSwitchboard();
  const { caps, errors, loading, domain } = sb;

  const available = useMemo(
    () =>
      MODES.filter(
        (m) =>
          m.value === 'board' ||
          (m.value === 'operate' && caps.operationsConsole) ||
          (m.value === 'analyze' && caps.analytics) ||
          (m.value === 'wallboard' && caps.wallboard),
      ),
    [caps],
  );
  const [stored, setStored] = usePersistentState<Mode>('mode', 'board', oneOf<Mode>('board', 'operate', 'analyze', 'wallboard'));
  const mode: Mode = available.some((m) => m.value === stored) ? stored : 'board';
  const setMode = useCallback((m: Mode) => setStored(m), [setStored]);

  // Bare 1-4 switch modes, except while typing.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.ctrlKey || e.metaKey || e.altKey) return;
      const t = e.target as HTMLElement | null;
      if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return;
      const m = MODES.find((x) => x.key === e.key);
      if (!m || !available.some((a) => a.value === m.value)) return;
      e.preventDefault();
      setMode(m.value);
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [available, setMode]);

  const readErrors = (['users', 'calls', 'queues', 'agents'] as const).map((k) => errors[k]).filter(Boolean) as string[];
  const showRail = mode === 'board' || mode === 'operate';

  return (
    <CompactPage
      marker={marker}
      title="Virtual Switchboard"
      subtitle={domain}
      subtitleControl={multiDomain ? <ShellDomainPicker onPick={onPickDomain} /> : undefined}
      loading={loading && sb.users.length === 0}
      start={
        available.length > 1 ? (
          <Stack direction="row" alignItems="center" spacing={1.5}>
            <Tabs
              variant="pill"
              value={mode}
              onChange={(v) => setMode(v as Mode)}
              options={available.map((m) => ({ value: m.value, label: m.label, icon: m.icon }))}
            />
            <Typography variant="caption" color="text.secondary" sx={{ display: 'none', '@media (min-width: 1800px)': { display: 'block' } }}>
              Keys {available.map((m) => m.key).join(' ')}
            </Typography>
          </Stack>
        ) : null
      }
      end={
        <>
          <KpiStrip />
          <HeaderStatus />
          <StatusSwitcher />
        </>
      }
    >
      {readErrors.length ? (
        <Box sx={{ mb: 1.5, flexShrink: 0 }}>
          <Alert severity="warning" title="Some data could not be loaded">
            {readErrors.map((m) => (
              <div key={m}>{m}</div>
            ))}
          </Alert>
        </Box>
      ) : null}

      <Box sx={{ flex: 1, minHeight: 0, display: 'flex', gap: 2 }}>
        <Box sx={{ flex: 1, minWidth: 0, overflowY: 'auto', pr: 0.5, pt: 1 }}>
          {mode === 'board' ? <RealTimeView /> : null}
          {mode === 'operate' ? <OperateView /> : null}
          {mode === 'analyze' ? <AnalyzeView /> : null}
          {mode === 'wallboard' ? <WallboardView /> : null}
        </Box>
        {showRail ? (
          <Box
            component="aside"
            aria-label="My calls, call parks and dial pad"
            sx={{
              width: 340,
              flexShrink: 0,
              display: { xs: 'none', lg: 'flex' },
              flexDirection: 'column',
              minHeight: 0,
              borderLeft: 1,
              borderColor: 'divider',
              pl: 2,
            }}
          >
            <OperatorRail />
          </Box>
        ) : null}
      </Box>
    </CompactPage>
  );
}

// ---------------------------------------------------------------------------
// Header pieces
// ---------------------------------------------------------------------------

function HeaderStatus() {
  const { Stack, Chip, Tooltip, Icon } = useKit();
  const { operator, domain } = useSwitchboard();
  const who = operator.ext ? `${operator.displayName} (${operator.ext})` : operator.displayName;
  const detail = [
    operator.scope || 'Unknown scope',
    operator.ext ? `extension ${operator.ext}@${operator.domain}` : 'no extension on this sign-in',
    operator.domain !== domain ? `viewing ${domain}` : '',
  ]
    .filter(Boolean)
    .join(' · ');
  return (
    <Stack direction="row" spacing={1} alignItems="center">
      <LivePill />
      <Tooltip title={detail} arrow>
        <Chip size="small" variant="outlined" icon={<Icon name="lucide:user" size={14} />} label={who} />
      </Tooltip>
    </Stack>
  );
}

function LivePill() {
  const now = useNow();
  const { Chip, Tooltip, Icon } = useKit();
  const { lastOk, paused, budgetUsed, caps, operator, live } = useSwitchboard();
  const key = caps.domainCalls || operator.ext ? 'calls' : 'queues';
  const at = lastOk(key);
  const pushed = live[key].state === 'live';
  let label = 'Connecting';
  let color: 'success' | 'warning' | 'default' = 'default';
  let icon = 'lucide:wifi-off';
  if (paused) {
    label = 'Paused';
    icon = 'lucide:pause';
  } else if (pushed && at != null && now - at < 75000) {
    label = 'Live';
    color = 'success';
    icon = 'lucide:zap';
  } else if (at != null && now - at < 15000) {
    label = 'Live';
    color = 'success';
    icon = 'lucide:wifi';
  } else if (at != null) {
    label = 'Reconnecting';
    color = 'warning';
  }
  const title = paused
    ? 'Updates pause while this tab is hidden and resume when you come back.'
    : pushed
      ? `Live from Flow streams, checked against the API. Last read ${formatAgo(at, now)}. ${budgetUsed()} of 100 requests used this minute.`
      : `Refreshing every few seconds through the Flow API. Last update ${formatAgo(at, now)}. ${budgetUsed()} of 100 requests used this minute.`;
  return (
    <Tooltip title={title} arrow>
      <Chip size="small" color={color} icon={<Icon name={icon} size={14} />} label={label} sx={{ fontWeight: 700 }} />
    </Tooltip>
  );
}

function StatusSwitcher() {
  const { Select } = useKit();
  const sb = useSwitchboard();
  const { run, isPending } = useActions();
  const { me, operator, domain, contactsByUser, myQueues, config, api } = sb;

  // The switcher only applies to an agent in the domain being viewed.
  const here = !!operator.ext && operator.domain === domain;
  if (!me || !here) return null;

  const presence = contactsByUser.get(operator.ext)?.presence ?? '';
  const current = resolveCurrentStatus(me, presence) || 'Online';
  const custom = config.customStatuses.filter(
    (c) => !DEFAULT_STATUS_OPTIONS.some((d) => d.toLowerCase() === c.toLowerCase()),
  );
  const options = [...DEFAULT_STATUS_OPTIONS, ...custom];
  if (!options.some((o) => o.toLowerCase() === current.toLowerCase())) options.push(current);

  const apply = (status: string) =>
    run(
      'status',
      async () => {
        const message = status === 'Online' || status === 'Offline' || status === 'End Shift' ? '' : status;
        await ns.setStatusMessage(api, domain, operator.ext, message);
        await ns.createAgentLog(api, domain, operator.ext, status).catch(() => undefined);
        const aid = agentId(operator.ext, domain);
        if (status === 'Do Not Disturb') return;
        if (status === 'Single Call') {
          for (const q of myQueues) await ns.setTakingCalls(api, domain, q, aid, false).catch(() => undefined);
          return;
        }
        const on = status === 'Online';
        for (const q of myQueues) await ns.setTakingCalls(api, domain, q, aid, on);
      },
      {
        success: `Status set to ${status}`,
        failure: `Could not set your status to ${status}. Your queues may be unchanged.`,
      },
    ).then(() => {
      sb.reloadAllRosters();
      sb.refresh(['agents', 'users']);
    });

  const tone: Tone = statusTone(current);
  return (
    <Select
      size="small"
      label="My status"
      value={options.find((o) => o.toLowerCase() === current.toLowerCase()) ?? current}
      disabled={isPending('status')}
      onChange={(e: React.ChangeEvent<HTMLInputElement>) => void apply(String(e.target.value))}
      // No option icons: Horizon's Select renders the chosen option's icon as a
      // block above the text in the closed field, on top of the label (seen live).
      options={options.map((o) => ({ value: o, label: o }))}
      SelectDisplayProps={{ 'aria-label': 'My status' }}
      sx={{ minWidth: 170, '& .MuiSelect-select': { color: toneText(tone), fontWeight: 600 } }}
    />
  );
}

function ShellDomainPicker({ onPick }: { onPick: (d: string) => void }) {
  const { api, domain } = useSwitchboard();
  return <DomainPicker api={api} domain={domain} onPick={onPick} compact />;
}

/** Opens the panel Call Flow asked for ("Open in Virtual Switchboard"). */
function HandoffReceiver() {
  const panels = usePanels();
  useEffect(() => {
    const h = takeHandoff();
    if (!h) return;
    if (h.kind === 'user') panels.openUser(h.user, h.tab);
    else panels.openQueue(h.queue);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  return null;
}

// ---------------------------------------------------------------------------
// KPI strip
// ---------------------------------------------------------------------------

function KpiStrip() {
  const now = useNow();
  const { Stack, Typography, Box } = useKit();
  const { queues, agentRows } = useSwitchboard();
  const k = deriveKpis(queues, agentRows, now);
  const band = waitBand(k.longestSeconds);
  const items: Array<{ label: string; value: string; tone: Tone | 'default' }> = [
    { label: 'Waiting', value: String(k.waiting), tone: k.waiting > 0 ? 'error' : 'default' },
    {
      label: 'Longest',
      value: formatMinSec(k.longestSeconds),
      tone: band === 'critical' ? 'error' : band === 'long' ? 'warning' : 'default',
    },
    { label: 'Available', value: String(k.available), tone: 'success' },
    { label: 'On call', value: String(k.onCall), tone: 'default' },
  ];
  return (
    <Stack direction="row" role="group" aria-label="Live totals" divider={<Box sx={{ width: '1px', bgcolor: 'divider' }} />} spacing={2}>
      {items.map((i) => (
        <Stack key={i.label} alignItems="center" sx={{ minWidth: 56 }}>
          <Typography
            sx={{
              fontSize: 20,
              lineHeight: 1.1,
              fontWeight: 800,
              fontVariantNumeric: 'tabular-nums',
              color: i.tone === 'default' ? 'text.primary' : toneText(i.tone),
            }}
          >
            {i.value}
          </Typography>
          <Typography sx={{ fontSize: 10, fontWeight: 700, letterSpacing: 0.8, textTransform: 'uppercase', color: 'text.secondary' }}>
            {i.label}
          </Typography>
        </Stack>
      ))}
    </Stack>
  );
}

