/**
 * Wallboard rules, ported from the Engage wallboard: the layout
 * (wallboardLayout.ts, exactly), the operator's settings
 * (useWallboardSettings.ts) and threshold alerting (queueAlerts.ts).
 *
 * Pure. The view wires them to the measured box, the settings store, the
 * clock and the chime.
 */
import { CRITICAL_WAIT_SECONDS, LONG_WAIT_SECONDS, waitBand } from '../../model/queues';
import { formatMinSec } from '../../model/format';

// ---------------------------------------------------------------------------
// Layout (R6): how many tiles fit, how they are arranged, how big the type is
// ---------------------------------------------------------------------------

export interface WallboardGrid {
  columns: number;
  rows: number;
}

/**
 * A tile reads best a little wider than tall: the metric row is horizontal,
 * and a tall narrow tile wastes its height on the caller list while cramping
 * the three numbers that matter most.
 */
const TARGET_TILE_ASPECT = 1.45;

/**
 * Arrange `count` tiles into the grid whose tile shape is closest to the
 * target. A tile's aspect is `viewportAspect * rows / columns`, compared in log
 * space (twice too wide is as wrong as half as wide), plus the fraction of the
 * grid left empty, so an exact fit wins a near-tie: on 16:9, four tiles are a
 * 2x2, not a 3x2 with two holes. Strictly-less keeps the FEWER columns on a
 * tie, which is the larger tile.
 */
export function wallboardGrid(count: number, viewportAspect: number): WallboardGrid {
  if (!Number.isFinite(count) || count <= 0) return { columns: 1, rows: 1 };
  const aspect = Number.isFinite(viewportAspect) && viewportAspect > 0 ? viewportAspect : 16 / 9;

  let best: WallboardGrid = { columns: 1, rows: count };
  let bestError = Infinity;
  for (let columns = 1; columns <= count; columns += 1) {
    const rows = Math.ceil(count / columns);
    const tileAspect = (aspect * rows) / columns;
    const waste = (columns * rows - count) / count;
    const error = Math.abs(Math.log(tileAspect / TARGET_TILE_ASPECT)) + waste;
    if (error < bestError) {
      bestError = error;
      best = { columns, rows };
    }
  }
  return best;
}

/** A tier, not a font size: the tile's whole composition changes together. Thresholds are tile HEIGHT in px. */
export type WallboardDensity = 'compact' | 'regular' | 'roomy' | 'huge';

export function wallboardDensity(tileHeight: number): WallboardDensity {
  if (!Number.isFinite(tileHeight) || tileHeight <= 0) return 'regular';
  if (tileHeight < 170) return 'compact';
  if (tileHeight < 280) return 'regular';
  if (tileHeight < 420) return 'roomy';
  return 'huge';
}

export interface WallboardTypeScale {
  /** The three big numbers, px. */
  metric: number;
  /** Their labels, px. */
  metricLabel: number;
  /** The queue name in the tile header, px. */
  title: number;
  /** A waiting-caller row, px. */
  caller: number;
  /** How many waiting callers to list. Zero means: no list at all. */
  callerRows: number;
  /** Tile padding, theme spacing units (8px each). */
  padding: number;
}

/**
 * The Engage tiers in pixels (its Tailwind steps: text-2xl/3xl/5xl/7xl for
 * the numbers, 3xs=10 and 2xs=11 for the smallest labels, p-2/3/4/6 padding).
 * At `compact` the caller list cannot be read across a room anyway, so the
 * tile spends every pixel on the three numbers.
 */
const SCALES: Record<WallboardDensity, WallboardTypeScale> = {
  compact: { metric: 24, metricLabel: 10, title: 14, caller: 12, callerRows: 0, padding: 1 },
  regular: { metric: 30, metricLabel: 11, title: 16, caller: 12, callerRows: 2, padding: 1.5 },
  roomy: { metric: 48, metricLabel: 12, title: 20, caller: 14, callerRows: 4, padding: 2 },
  huge: { metric: 72, metricLabel: 14, title: 30, caller: 18, callerRows: 6, padding: 3 },
};

export function wallboardTypeScale(density: WallboardDensity): WallboardTypeScale {
  return SCALES[density];
}

/**
 * The most tiles that still read at `regular` or better on this box. Capped
 * at 24: past that a person cannot track the tiles, whatever the arithmetic
 * says. More queues than this page (and rotate) rather than shrink.
 */
export function tilesPerPage(width: number, height: number): number {
  if (!Number.isFinite(width) || !Number.isFinite(height) || width <= 0 || height <= 0) return 8;
  const aspect = width / height;
  let last = 1;
  for (let count = 1; count <= 24; count += 1) {
    const { columns, rows } = wallboardGrid(count, aspect);
    const tileHeight = height / rows;
    const tileWidth = width / columns;
    if (wallboardDensity(tileHeight) === 'compact' || tileWidth < 240) break;
    last = count;
  }
  return last;
}

/** Pages of at most `perPage`, in order. Always at least one page, so `[0]` is safe. */
export function paginate<T>(items: readonly T[], perPage: number): T[][] {
  const size = Number.isFinite(perPage) && perPage > 0 ? Math.floor(perPage) : items.length || 1;
  if (items.length === 0) return [[]];
  const pages: T[][] = [];
  for (let i = 0; i < items.length; i += size) pages.push(items.slice(i, i + size));
  return pages;
}

// ---------------------------------------------------------------------------
// Settings (per viewer, this browser)
// ---------------------------------------------------------------------------

export interface WallboardSettings {
  privacyMode: boolean;
  /** Seconds before a wait turns amber (the operator's override of the platform 2:00). */
  longWaitSec: number;
  /** Seconds before a wait turns red and alerts (override of 3:00). */
  criticalWaitSec: number;
  /** Play a chime when a caller crosses a threshold. Off until asked for. */
  alertSound: boolean;
  autoRotate: boolean;
  autoRotateIntervalSec: number;
}

export const MIN_LONG_WAIT_SEC = 5;
export const MIN_CRITICAL_WAIT_SEC = 10;
export const MIN_ROTATE_SEC = 5;

export const DEFAULT_WALLBOARD_SETTINGS: WallboardSettings = {
  privacyMode: false,
  longWaitSec: LONG_WAIT_SECONDS,
  criticalWaitSec: CRITICAL_WAIT_SECONDS,
  alertSound: false,
  autoRotate: false,
  autoRotateIntervalSec: 30,
};

function num(raw: unknown, min: number, fallback: number): number {
  return typeof raw === 'number' && Number.isFinite(raw) && raw >= min ? Math.round(raw) : fallback;
}

function bool(raw: unknown, fallback: boolean): boolean {
  return typeof raw === 'boolean' ? raw : fallback;
}

/** Validate a stored value field by field: a bad field falls back alone, not the whole set. */
export function normalizeSettings(raw: unknown): WallboardSettings {
  const o = raw && typeof raw === 'object' && !Array.isArray(raw) ? (raw as Record<string, unknown>) : {};
  const d = DEFAULT_WALLBOARD_SETTINGS;
  return {
    privacyMode: bool(o.privacyMode, d.privacyMode),
    longWaitSec: num(o.longWaitSec, MIN_LONG_WAIT_SEC, d.longWaitSec),
    criticalWaitSec: num(o.criticalWaitSec, MIN_CRITICAL_WAIT_SEC, d.criticalWaitSec),
    alertSound: bool(o.alertSound, d.alertSound),
    autoRotate: bool(o.autoRotate, d.autoRotate),
    autoRotateIntervalSec: num(o.autoRotateIntervalSec, MIN_ROTATE_SEC, d.autoRotateIntervalSec),
  };
}

export interface Thresholds {
  long: number;
  critical: number;
}

/** Critical below long would invert the bands and paint a fresh call red, so it is clamped, never refused. */
export function thresholdsOf(longWaitSec: number, criticalWaitSec: number): Thresholds {
  return { long: longWaitSec, critical: Math.max(criticalWaitSec, longWaitSec) };
}

// ---------------------------------------------------------------------------
// Alerts (D9): once per caller per band
// ---------------------------------------------------------------------------

export type AlertBand = 'long' | 'critical';

/** A waiting caller, as the detector sees one. */
export interface AlertCandidate {
  /** Stable per-call identity (the switch's call id). */
  id: string;
  queueExt: string;
  queueName: string;
  /** Caller name or number, for the banner when privacy is off. */
  callerLabel: string;
  waitSeconds: number;
}

export interface QueueAlert extends AlertCandidate {
  /** This crossing: one call can legitimately raise two (long, then critical). */
  key: string;
  band: AlertBand;
}

export function alertKey(id: string, band: AlertBand): string {
  return `${band}:${id}`;
}

const BANDS: readonly AlertBand[] = ['long', 'critical'];

/**
 * Crossings that have happened and not yet been announced. A call first seen
 * past BOTH thresholds (a freshly opened wallboard, a laptop waking) raises
 * only the critical alert; the long one it skipped is returned in `alsoSeen`
 * so the caller records it and it cannot fire a second later.
 */
export function detectQueueAlerts(
  candidates: readonly AlertCandidate[],
  thresholds: Thresholds,
  announced: ReadonlySet<string>,
): { alerts: QueueAlert[]; alsoSeen: string[] } {
  const alerts: QueueAlert[] = [];
  const alsoSeen: string[] = [];
  for (const c of candidates) {
    const band = waitBand(c.waitSeconds, thresholds);
    if (band === 'ok') continue;
    const reached = BANDS.slice(0, BANDS.indexOf(band) + 1).reverse();
    const unannounced = reached.filter((b) => !announced.has(alertKey(c.id, b)));
    if (!unannounced.length) continue;
    const [top, ...rest] = unannounced;
    alerts.push({ ...c, key: alertKey(c.id, top), band: top });
    for (const b of rest) alsoSeen.push(alertKey(c.id, b));
  }
  return { alerts, alsoSeen };
}

/**
 * Forget crossings for callers no longer waiting (answered, or hung up). Keeps
 * a wall display that runs for weeks from growing the set without bound, and
 * lets a reissued call id alert again.
 */
export function pruneAnnounced(announced: ReadonlySet<string>, liveIds: ReadonlySet<string>): Set<string> {
  const next = new Set<string>();
  for (const key of announced) {
    if (liveIds.has(key.slice(key.indexOf(':') + 1))) next.add(key);
  }
  return next;
}

/** The most urgent of a batch: critical first, then the longest wait. */
export function mostUrgent(alerts: readonly QueueAlert[]): QueueAlert | null {
  let best: QueueAlert | null = null;
  for (const a of alerts) {
    if (
      !best ||
      (a.band === 'critical' && best.band !== 'critical') ||
      (a.band === best.band && a.waitSeconds > best.waitSeconds)
    ) {
      best = a;
    }
  }
  return best;
}

/** "Critical wait in Sales: (813) 555-0142 has been waiting 3:05." */
export function describeAlert(alert: QueueAlert, privacy: boolean): string {
  const queue = alert.queueName.trim() || alert.queueExt;
  const caller = privacy ? 'A caller' : alert.callerLabel || 'A caller';
  const band = alert.band === 'critical' ? 'Critical wait' : 'Long wait';
  return `${band} in ${queue}: ${caller} has been waiting ${formatMinSec(alert.waitSeconds)}.`;
}
