/**
 * Live feeds from Flow's `sdk.streams`.
 *
 * Flow 0.3 relays the domain-wide feeds the Engage switchboard reads off the
 * :8001 socket, through the host and with no credential in the app:
 *
 *   calls.onDomainCalls     every call in the domain (supervisor scopes)
 *   calls.onExtension       one extension's calls (anyone, for their own)
 *   queues.onDomainQueues   queue stats and agent changes (supervisor scopes)
 *
 * Grants are derived from this file: the platform finds each
 * `.<subject>.<method>(` call in the source maps, so every method is written
 * out literally at its call site. Never pick a method at runtime.
 *
 * Each event tells the data provider which feed changed (and which queue, when
 * the event names one), and the provider reads that feed from the API now
 * instead of waiting for its interval. While a feed is live its fast poll
 * becomes a slow safety net. A feed the host refuses (an agent asking for
 * domain queues, a Super User managing another domain) simply stays on the
 * poller. The stream payloads are not applied to the board yet: the board is
 * built on NetSapiens v2 records and the payloads are a different shape, so
 * that waits until it has been checked against real traffic (see
 * tools/stream-inspector).
 *
 * The SDK object is created in App and handed over here, because the pages
 * are rendered by the host and do not receive it.
 */
import type { CallActivity, QueueStats, AgentStatus, RemoteAppSDK, StreamStatus, Subscription } from '@netsapiens/flow-sdk';

let current: RemoteAppSDK | null = null;

/** Called by App once the SDK exists. Returns the undo. */
export function provideStreams(sdk: RemoteAppSDK): () => void {
  current = sdk;
  return () => {
    if (current === sdk) current = null;
  };
}

export type FeedKey = 'calls' | 'queues';

/** Where a feed stands, reduced to what the console shows. */
export type FeedState = 'off' | 'pending' | 'live' | 'down' | 'refused';

export interface FeedStatus {
  state: FeedState;
  /** The host's own words for a refusal, safe to show. */
  message?: string;
}

export interface LiveFeedOptions {
  /** The domain the board shows. Events for any other domain are ignored. */
  domain: string;
  /** Read the whole domain (supervisor scopes), not just `ext`. */
  domainWide: boolean;
  /** The operator's own extension, for the own-calls feed. */
  ext: string;
  /** Something changed on `feed`; `queue` when the event names one. */
  onChange: (feed: FeedKey, queue?: string) => void;
  /** A queue's roster changed. */
  onAgent: (queue: string) => void;
  onStatus: (feed: FeedKey, status: FeedStatus) => void;
}

export function reduceStatus(s: StreamStatus): FeedStatus {
  switch (s.state) {
    case 'live':
      return { state: 'live' };
    case 'pending':
      return { state: 'pending' };
    case 'refused':
      return { state: 'refused', message: s.message };
    case 'unavailable':
      return { state: 'down' };
    default:
      // 'unconfirmed' (a host without sdk.streams) and any state added later.
      return { state: 'off' };
  }
}

/** Open the board's feeds. Returns the teardown; safe to call with no SDK. */
export function openLiveFeeds(opts: LiveFeedOptions): () => void {
  const sdk = current;
  if (!sdk?.streams) {
    opts.onStatus('calls', { state: 'off' });
    opts.onStatus('queues', { state: 'off' });
    return () => {};
  }
  const subs: Array<[FeedKey, Subscription]> = [];
  const here = (d: string | undefined) => !d || d === opts.domain;

  const onCall = (c: CallActivity) => {
    if (!here(c.domain)) return;
    opts.onChange('calls', c.through?.user || undefined);
  };
  const callOptions = { onStatus: (s: StreamStatus) => opts.onStatus('calls', reduceStatus(s)) };
  try {
    if (opts.domainWide) {
      subs.push(['calls', sdk.streams.calls.onDomainCalls({ updated: onCall, ended: onCall }, callOptions)]);
    } else if (opts.ext) {
      subs.push(['calls', sdk.streams.calls.onExtension(opts.ext, { updated: onCall, ended: onCall }, callOptions)]);
    } else {
      opts.onStatus('calls', { state: 'off' });
    }
  } catch (e) {
    console.warn('[switchboard] calls stream unavailable:', e);
    opts.onStatus('calls', { state: 'off' });
  }

  if (opts.domainWide) {
    const onStats = (q: QueueStats) => {
      if (here(q.domain)) opts.onChange('queues', q.queue);
    };
    const onAgent = (a: AgentStatus) => {
      if (here(a.domain) && a.queue) opts.onAgent(a.queue);
    };
    try {
      subs.push([
        'queues',
        sdk.streams.queues.onDomainQueues(
          { stats: onStats, agentUpdated: onAgent, agentAdded: onAgent, agentRemoved: onAgent },
          { onStatus: (s: StreamStatus) => opts.onStatus('queues', reduceStatus(s)) },
        ),
      ]);
    } catch (e) {
      console.warn('[switchboard] queues stream unavailable:', e);
      opts.onStatus('queues', { state: 'off' });
    }
  } else {
    opts.onStatus('queues', { state: 'off' });
  }

  // onStatus reports changes only; report where each stands now.
  for (const [feed, s] of subs) opts.onStatus(feed, reduceStatus(s.status));
  return () => {
    for (const [, s] of subs) {
      try {
        s.unsubscribe();
      } catch {
        /* best effort */
      }
    }
  };
}
