/**
 * A directory contact on the Real-Time board (the Engage ContactCard):
 * presence dot, name, portal status with its timer, headset verdict with the
 * queue-membership hover, voicemail badge, and up to two live lines.
 */
import type { Contact, Line, QueueMember } from '../../types';
import { useSwitchboard } from '../../data/SwitchboardData';
import { useActions } from '../../data/actions';
import { usePanels } from '../../data/panels';
import * as ns from '../../api/ns';
import { HEADSET, callsLabel, summariseHeadset } from '../../model/agents';
import { formatPhone, formatTimer } from '../../model/format';
import { useKit } from '../../ui/kit';
import { ActionIcon, Dot, Pill, Timer, tint, toneColor } from '../../ui/bits';
import type { Tone } from '../../ui/bits';

const LINE_STYLE: Record<Line['status'], { label: string; tone: Tone; title: string }> = {
  ringing: { label: 'Ringing', tone: 'warning', title: 'Incoming call is ringing, waiting for answer' },
  dialing: { label: 'Dialing', tone: 'info', title: 'Outbound call is being placed, waiting for the other party to answer' },
  active: { label: 'Active', tone: 'success', title: 'Call is connected and in progress' },
  held: { label: 'On Hold', tone: 'warning', title: 'Call is on hold, the other party is hearing hold music' },
  unknown: { label: 'Active', tone: 'success', title: 'Call is connected and in progress' },
};

function presenceOf(c: Contact): { tone: Tone; pulse: boolean; title: string; ringing: boolean; onCall: boolean } {
  const dispatch = String(c.agent?.['callqueue-agent-availability-for-dispatch'] ?? '').toLowerCase();
  const p = c.presence;
  const onCall = c.isOnCall || c.lines.length > 0;
  const ringing = c.lines.some((l) => l.status === 'ringing' || l.status === 'dialing');
  const dnd = c.dnd;
  const online = dispatch === 'available' || p === 'open' || p === 'active';
  const unavailable =
    !onCall && !dnd && !online && (p === 'away' || p === 'busy' || dispatch === 'unavailable' || (!!c.agent && dispatch !== 'available'));

  let title: string;
  if (onCall && dnd) title = 'On Call (DND enabled): currently on a call, DND will block new calls';
  else if (ringing) title = 'Ringing: their phone is ringing and nobody has answered yet';
  else if (onCall) title = 'On Call: this user is currently on a phone call';
  else if (dnd) title = 'Do Not Disturb: this user has DND enabled and will not receive calls';
  else if (unavailable) title = 'Unavailable: this user is logged in but not available to take calls';
  else if (online) title = 'Available: this user is online and ready to receive calls';
  else title = 'Offline: this user is not currently logged in';

  let tone: Tone = 'neutral';
  if (ringing) tone = 'warning';
  else if (onCall) tone = 'info';
  else if (dnd) tone = 'error';
  else if (unavailable) tone = 'warning';
  else if (online) tone = 'success';
  return { tone, pulse: ringing, title, ringing, onCall };
}

export function ContactCard({ contact, memberships }: { contact: Contact; memberships: QueueMember[] }) {
  const { Paper, Stack, Typography, Box, Tooltip, Button } = useKit();
  const sb = useSwitchboard();
  const { run, isPending } = useActions();
  const { openUser } = usePanels();
  const { operator, domain, caps, vmCounts, queues, api } = sb;
  const isMe = contact.user === operator.ext && operator.domain === domain;
  const pres = presenceOf(contact);
  const lines = contact.lines.slice(0, 2);
  const canVoicemail = caps.voicemailManagement || isMe;
  const vm = vmCounts[contact.user] ?? 0;
  const canCall = !!operator.ext && operator.domain === domain && !isMe;

  const borderColor = isMe ? 'primary.main' : pres.ringing ? tint('warning', 0.6) : pres.onCall ? tint('info', 0.5) : 'divider';
  const bg = pres.ringing ? tint('warning', 0.05) : pres.onCall ? tint('info', 0.05) : 'background.paper';

  const call = () =>
    run(`call:${contact.user}`, () => ns.originate(api, operator.domain, operator.ext, contact.user), {
      success: `Calling ${contact.name} (${contact.user})`,
      failure: 'Failed to place call.',
    }).then(() => sb.refresh(['calls']));

  return (
    <Paper
      variant="outlined"
      sx={{
        width: 320,
        maxWidth: '100%',
        p: 1.5,
        borderWidth: 2,
        borderColor,
        bgcolor: bg,
        outline: isMe ? '3px solid' : 'none',
        outlineColor: tint('primary', 0.2),
        transition: 'box-shadow 120ms',
        '&:hover': { boxShadow: 2 },
      }}
    >
      <Stack direction="row" spacing={0.75} alignItems="center">
        <Dot tone={pres.tone} size={13} pulse={pres.pulse} title={pres.title} />
        <Tooltip title={`${contact.name} (Extension ${contact.user})`} arrow>
          <Button
            variant="text"
            color="inherit"
            onClick={() => openUser(contact.user, canVoicemail ? 'voicemail' : 'history')}
            sx={{ p: 0, minWidth: 0, textTransform: 'none', fontWeight: 700, fontSize: 14, justifyContent: 'flex-start', overflow: 'hidden' }}
          >
            <Box component="span" sx={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
              {contact.name} ({contact.user})
            </Box>
          </Button>
        </Tooltip>
        {contact.portalStatus ? <PortalStatus contact={contact} /> : null}
        <Box sx={{ flex: 1 }} />
        {contact.agent || memberships.length ? (
          <HeadsetBadge contact={contact} memberships={memberships} queueNames={new Map(queues.map((q) => [q.ext, q.name]))} />
        ) : null}
        {canVoicemail && contact.voicemailEnabled ? (
          <Tooltip title={vm > 0 ? `${vm} new voicemail${vm === 1 ? '' : 's'}. Click to manage.` : 'Manage voicemails'} arrow>
            <Box sx={{ position: 'relative', display: 'inline-flex' }}>
              <ActionIcon icon="lucide:voicemail" label="Voicemail" onClick={() => openUser(contact.user, 'voicemail')} />
              {vm > 0 ? (
                <Box
                  sx={{
                    position: 'absolute',
                    top: 0,
                    right: 0,
                    minWidth: 16,
                    height: 16,
                    px: 0.5,
                    borderRadius: 8,
                    bgcolor: 'error.main',
                    color: 'error.contrastText',
                    fontSize: 10,
                    fontWeight: 800,
                    lineHeight: '16px',
                    textAlign: 'center',
                    pointerEvents: 'none',
                  }}
                >
                  {vm > 99 ? '99+' : vm}
                </Box>
              ) : null}
            </Box>
          </Tooltip>
        ) : null}
        {canCall ? (
          <ActionIcon
            icon="lucide:phone-outgoing"
            label={`Call ${contact.name} from your phone`}
            busy={isPending(`call:${contact.user}`)}
            onClick={() => void call()}
          />
        ) : null}
      </Stack>
      {contact.site || contact.department ? (
        <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 0.25, ml: 2.5 }} noWrap>
          {[contact.department, contact.site].filter(Boolean).join(' · ')}
        </Typography>
      ) : null}

      {lines.length ? (
        <Stack spacing={1} sx={{ mt: 1.25 }}>
          {lines.map((l, i) => (
            <LineRow key={l.call.key} line={l} index={i + 1} />
          ))}
        </Stack>
      ) : null}
    </Paper>
  );
}

function LineRow({ line, index }: { line: Line; index: number }) {
  const { Box, Stack, Typography, Icon, Tooltip } = useKit();
  const st = LINE_STYLE[line.status];
  const number = formatPhone(line.peerNumber);
  const name = line.peerName && line.peerName !== line.peerNumber ? line.peerName : number || 'Unknown';
  return (
    <Box sx={{ p: 1, borderRadius: 1, border: 1, borderColor: tint(st.tone, 0.3), bgcolor: tint(st.tone, 0.08) }}>
      <Stack direction="row" spacing={0.75} alignItems="center">
        <Tooltip title={line.direction === 'outbound' ? 'Outbound call' : 'Inbound call'} arrow>
          <Box sx={{ display: 'flex', color: line.direction === 'outbound' ? 'info.main' : 'success.main' }}>
            <Icon name={line.direction === 'outbound' ? 'lucide:phone-outgoing' : 'lucide:phone-incoming'} size={14} />
          </Box>
        </Tooltip>
        <Typography variant="caption" color="text.secondary" sx={{ fontWeight: 600 }}>
          Line {index}:
        </Typography>
        <Typography variant="caption" sx={{ fontWeight: 700, minWidth: 0 }} noWrap title={name}>
          {name}
        </Typography>
      </Stack>
      <Stack direction="row" spacing={1} alignItems="center" sx={{ mt: 0.5 }}>
        <Typography variant="caption" color="text.secondary" sx={{ fontVariantNumeric: 'tabular-nums' }}>
          {number || '-'}
        </Typography>
        <Tooltip title={st.title} arrow>
          <span>
            <Pill tone={st.tone} label={st.label} />
          </span>
        </Tooltip>
        <Box sx={{ flex: 1 }} />
        <Timer since={line.answeredAt ?? line.startedAt} title="Call duration" />
      </Stack>
    </Box>
  );
}

function PortalStatus({ contact }: { contact: Contact }) {
  const status = contact.portalStatus;
  const tone: Tone = contact.dnd ? 'error' : status.toLowerCase() === 'online' ? 'success' : 'warning';
  return (
    <Pill
      tone={tone}
      outlined
      title={`Status: ${status}`}
      label={
        <span style={{ display: 'inline-flex', gap: 6, alignItems: 'center', maxWidth: 150 }}>
          <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', maxWidth: 80 }}>{status}</span>
          {contact.lastUpdate ? <Timer since={contact.lastUpdate} format={formatTimer} /> : null}
        </span>
      }
    />
  );
}

function HeadsetBadge({
  contact,
  memberships,
  queueNames,
}: {
  contact: Contact;
  memberships: QueueMember[];
  queueNames: Map<string, string>;
}) {
  const { Box, Tooltip, Icon, Stack, Typography } = useKit();
  const s = summariseHeadset(contact.presence, memberships, contact.lines);
  const tone = HEADSET[s.state].tone;
  const body = (
    <Box sx={{ p: 0.5, minWidth: 220 }}>
      <Stack direction="row" spacing={1} alignItems="center">
        <Dot tone={tone} />
        <Typography variant="body2" sx={{ fontWeight: 700 }}>
          {s.title}
        </Typography>
      </Stack>
      <Typography variant="caption" sx={{ display: 'block', opacity: 0.85 }}>
        {s.subtitle}
      </Typography>
      {memberships.length ? (
        <>
          <Typography sx={{ mt: 1, fontSize: 10, fontWeight: 800, letterSpacing: 0.8, opacity: 0.8 }}>QUEUE MEMBERSHIPS</Typography>
          {memberships.map((m) => (
            <Stack key={`${m.queue}:${m.user}`} direction="row" spacing={1} alignItems="center" sx={{ mt: 0.25 }}>
              <Typography variant="caption" sx={{ fontWeight: 600, minWidth: 0, flex: 1 }} noWrap>
                {m.queue} {queueNames.get(m.queue) ?? ''}
              </Typography>
              <Typography variant="caption" sx={{ fontWeight: 700, color: m.status === 'available' && !m.loggedOut ? 'success.light' : 'inherit', opacity: m.status === 'available' ? 1 : 0.7 }}>
                {m.status === 'available' && !m.loggedOut ? 'Available' : 'Unavailable'}
              </Typography>
              <Typography variant="caption" sx={{ opacity: 0.75 }}>
                {callsLabel(m) || '-'}
              </Typography>
            </Stack>
          ))}
        </>
      ) : null}
      <Typography variant="caption" sx={{ display: 'block', mt: 1, opacity: 0.8 }}>
        {contact.portalStatus ? `Portal status: ${contact.portalStatus}` : 'No portal status set'}
      </Typography>
    </Box>
  );
  return (
    <Tooltip title={body} arrow enterDelay={200} leaveDelay={80}>
      <Box
        component="span"
        role="img"
        aria-label={`${contact.firstName || contact.user} headset: ${s.title}`}
        sx={{ display: 'inline-flex', color: toneColor(tone), p: 0.5 }}
      >
        <Icon name="lucide:headphones" size={18} />
      </Box>
    </Tooltip>
  );
}
