/**
 * The expanded queue (the Engage QueueExpandOverlay): callers on the left,
 * the agent roster on the right, in a wide side panel.
 */
import { useEffect, useMemo } from 'react';

import { useSwitchboard } from '../data/SwitchboardData';
import { ringStrategyLabel } from '../model/queues';
import { useKit } from '../ui/kit';
import { SectionTitle } from '../ui/bits';
import { QueueAgentList, QueueCallerList, queueAgentCounts } from '../views/realtime/QueueTile';

export function QueueExpandPanel({ queue, onClose }: { queue: string | null; onClose: () => void }) {
  const { SidePanel, Box, Typography, Icon, Button, Stack } = useKit();
  const { queues, contacts, reloadRoster } = useSwitchboard();
  const q = queues.find((x) => x.ext === queue) ?? null;
  const dnd = useMemo(() => new Map(contacts.map((c) => [c.user, c.dnd] as const)), [contacts]);

  useEffect(() => {
    if (queue) void reloadRoster(queue);
  }, [queue, reloadRoster]);

  const counts = q ? queueAgentCounts(q, dnd) : { available: 0, total: 0 };
  const calls = q ? q.waiting.length + q.active.length : 0;
  const ring = q ? ringStrategyLabel(q.dispatchType) : '';
  const waitingReal = q ? q.waiting.filter((c) => !c.placeholder).length : 0;

  return (
    <SidePanel
      open={queue !== null}
      onClose={onClose}
      width="xl"
      icon={<Icon name="lucide:list-ordered" size={20} />}
      title={q ? `${q.ext} - ${q.description || 'Unnamed Queue'}` : 'Queue'}
      subtitle={q ? [`${calls} call${calls === 1 ? '' : 's'}`, `${counts.available}/${counts.total} agents available`, ring].filter(Boolean).join(' · ') : undefined}
      footer={
        <Stack direction="row" justifyContent="flex-end" sx={{ width: '100%' }}>
          <Button variant="contained" onClick={onClose}>
            Done
          </Button>
        </Stack>
      }
    >
      {!q ? (
        <Typography color="text.secondary">That queue is no longer in this domain.</Typography>
      ) : (
        <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', md: '1fr 1fr' }, gap: 3 }}>
          <Box>
            <SectionTitle icon="lucide:phone-incoming" title={`Waiting & Active Calls (${calls})`} />
            <Typography sx={{ fontSize: 10, fontWeight: 800, letterSpacing: 1, color: 'text.secondary', mb: 1 }}>
              WAITING ({waitingReal || q.reportedWaiting})
            </Typography>
            <QueueCallerList queue={q} />
          </Box>
          <Box>
            <SectionTitle icon="lucide:users" title={`Agents (${counts.available}/${counts.total})`} />
            <QueueAgentList queue={q} />
          </Box>
        </Box>
      )}
    </SidePanel>
  );
}
