/**
 * Request budget for the host API proxy.
 *
 * The proxy allows an app 100 requests per rolling 60 seconds. Background
 * polling must never starve a click, so every request is counted in one
 * sliding window and two views of the same client are handed out:
 *
 *   - `background` refuses once the window holds BACKGROUND_LIMIT requests
 *     (the poller treats that as "skip this tick", not as an error);
 *   - `foreground` (clicks, panel reads) may use the headroom up to HARD_LIMIT.
 *
 * A 429 / RATE_LIMIT_EXCEEDED from the proxy opens a cooldown during which the
 * background view refuses everything, so the app backs off instead of
 * hammering a limit it has already hit.
 */
import type { FlowApiClient } from '@netsapiens/flow-sdk';

const WINDOW_MS = 60_000;
export const BACKGROUND_LIMIT = 72;
export const HARD_LIMIT = 96;
const COOLDOWN_MS = 15_000;

export class BudgetExceeded extends Error {
  constructor(readonly background: boolean) {
    super(
      background
        ? 'Background refresh deferred to stay inside the request budget.'
        : 'Too many requests in the last minute. Wait a few seconds and try again.',
    );
    this.name = 'BudgetExceeded';
  }
}

export function isRateLimitError(e: unknown): boolean {
  if (!e || typeof e !== 'object') return false;
  const o = e as { code?: unknown; statusCode?: unknown; status?: unknown; message?: unknown };
  return (
    o.code === 'RATE_LIMIT_EXCEEDED' ||
    o.statusCode === 429 ||
    o.status === 429 ||
    (typeof o.message === 'string' && /rate.?limit|too many requests|\b429\b/i.test(o.message))
  );
}

export class RequestBudget {
  private stamps: number[] = [];
  private cooldownUntil = 0;
  readonly background: FlowApiClient;
  readonly foreground: FlowApiClient;

  constructor(private readonly api: FlowApiClient) {
    this.background = this.view(true);
    this.foreground = this.view(false);
  }

  private prune(now: number): void {
    const cutoff = now - WINDOW_MS;
    while (this.stamps.length && this.stamps[0] <= cutoff) this.stamps.shift();
  }

  /** Requests counted in the current window. */
  used(now = Date.now()): number {
    this.prune(now);
    return this.stamps.length;
  }

  cooling(now = Date.now()): boolean {
    return now < this.cooldownUntil;
  }

  canBackground(now = Date.now()): boolean {
    return !this.cooling(now) && this.used(now) < BACKGROUND_LIMIT;
  }

  private admit(background: boolean): void {
    const now = Date.now();
    this.prune(now);
    if (background && (this.cooling(now) || this.stamps.length >= BACKGROUND_LIMIT)) {
      throw new BudgetExceeded(true);
    }
    if (!background && this.stamps.length >= HARD_LIMIT) throw new BudgetExceeded(false);
    this.stamps.push(now);
  }

  private async guard<T>(background: boolean, fn: () => Promise<T>): Promise<T> {
    this.admit(background);
    try {
      return await fn();
    } catch (e) {
      if (isRateLimitError(e)) this.cooldownUntil = Date.now() + COOLDOWN_MS;
      throw e;
    }
  }

  private view(background: boolean): FlowApiClient {
    const api = this.api;
    return {
      get: <T,>(path: string, params?: Record<string, unknown>) =>
        this.guard<T>(background, () => api.get<T>(path, params)),
      post: <T,>(path: string, data: unknown) => this.guard<T>(background, () => api.post<T>(path, data)),
      put: <T,>(path: string, data: unknown) => this.guard<T>(background, () => api.put<T>(path, data)),
      delete: <T,>(path: string) => this.guard<T>(background, () => api.delete<T>(path)),
      getBaseUrl: () => api.getBaseUrl(),
    };
  }
}
