/**
 * The user side panel: one extension's voicemail, call handling and call
 * history, opened from a contact card or the operator rail
 * (`usePanels().openUser(ext, tab)`).
 *
 * Scope rules match the Engage switchboard: the operator can always open their
 * own extension; another user's voicemail needs voicemail management and their
 * call handling or history needs user management. A tab the scope does not
 * allow still shows, and says why.
 *
 * A tab's body mounts the first time it is shown and then stays mounted while
 * the panel is open, so switching tabs neither re-fetches nor throws away
 * unsaved call handling edits.
 */
import type * as React from 'react';
import { useEffect, useRef, useState } from 'react';

import type { Contact } from '../types';
import { useSwitchboard } from '../data/SwitchboardData';
import { useKit } from '../ui/kit';
import { CallHandlingSection } from './CallHandlingSection';
import { CallHistorySection } from './CallHistorySection';
import { VoicemailSection } from './VoicemailSection';

export type UserPanelTab = 'voicemail' | 'handling' | 'history';

const TABS: UserPanelTab[] = ['voicemail', 'handling', 'history'];

const TAB_NOUN: Record<UserPanelTab, string> = {
  voicemail: 'voicemail',
  handling: 'call handling',
  history: 'call history',
};

/** Marks the voicemail tab body, so leaving the tab can pause its playback. */
const VOICEMAIL_ATTR = 'data-tvsb-user-voicemail';

function pauseVoicemailAudio(): void {
  if (typeof document === 'undefined') return;
  document.querySelectorAll<HTMLAudioElement>(`[${VOICEMAIL_ATTR}] audio`).forEach((a) => a.pause());
}

function hasName(c: Contact | undefined): c is Contact {
  return !!c && !!(c.firstName || c.lastName);
}

function initialsOf(c: Contact): string {
  return `${c.firstName.charAt(0)}${c.lastName.charAt(0)}`.toUpperCase();
}

export function UserPanel({ user, tab, onClose }: { user: string | null; tab: UserPanelTab; onClose: () => void }) {
  const { SidePanel, Tabs, Box, Stack, Avatar, Alert, Button, Icon } = useKit();
  const { operator, caps, domain, contactsByUser, vmCounts, reloadVoicemailCount } = useSwitchboard();

  // Follow the requested user and tab whenever either changes. This is done
  // while rendering (not in an effect) so a tab left over from the previous
  // user never mounts, and fetches, for the new one.
  const [opened, setOpened] = useState<{ user: string | null; tab: UserPanelTab }>({ user, tab });
  const [active, setActive] = useState<UserPanelTab>(tab);
  const [visited, setVisited] = useState<UserPanelTab[]>([tab]);
  /** The last extension shown, so the title holds steady while the drawer closes. */
  const [shown, setShown] = useState<string>(user ?? '');
  if (opened.user !== user || opened.tab !== tab) {
    setOpened({ user, tab });
    setActive(tab);
    setVisited([tab]);
    if (user) setShown(user);
  }

  const ext = user ?? shown;
  const contact = ext ? contactsByUser.get(ext) : undefined;
  const self = !!operator.ext && operator.ext === ext && operator.domain === domain;
  const allowed: Record<UserPanelTab, boolean> = {
    voicemail: self || caps.voicemailManagement,
    handling: self || caps.manageUsers,
    history: self || caps.manageUsers,
  };
  const voicemailOff = !!contact && !contact.voicemailEnabled;

  // The tab label shows the new-message count. Read it once when the panel
  // opens on someone whose count the background trickle has not reached yet.
  const canReadCount = allowed.voicemail && !voicemailOff;
  const countChecked = useRef<string | null>(null);
  useEffect(() => {
    if (!user) {
      countChecked.current = null;
      return;
    }
    if (!canReadCount || countChecked.current === user) return;
    countChecked.current = user;
    if (vmCounts[user] === undefined) void reloadVoicemailCount(user);
  }, [user, canReadCount, vmCounts, reloadVoicemailCount]);

  const selectTab = (next: UserPanelTab) => {
    if (next !== 'voicemail') pauseVoicemailAudio();
    setActive(next);
    setVisited((prev) => (prev.includes(next) ? prev : [...prev, next]));
  };

  const newCount = ext && canReadCount ? vmCounts[ext] ?? 0 : 0;
  const title = hasName(contact) ? `${contact.name} (${ext})` : ext;
  const subtitle = contact ? [contact.site, contact.department, contact.scope].filter(Boolean).join(' · ') : '';

  const renderTab = (t: UserPanelTab): React.ReactNode => {
    if (!allowed[t]) {
      return <Alert severity="info" message={`Your scope does not allow viewing another user's ${TAB_NOUN[t]}.`} />;
    }
    if (t === 'voicemail') {
      if (voicemailOff) return <Alert severity="info" message="Voicemail is turned off for this extension." />;
      return <VoicemailSection key={ext} user={ext} />;
    }
    if (t === 'handling') return <CallHandlingSection key={ext} user={ext} />;
    return <CallHistorySection key={ext} user={ext} />;
  };

  return (
    <SidePanel
      open={user !== null}
      onClose={onClose}
      width="lg"
      title={title}
      subtitle={subtitle || undefined}
      icon={
        <Avatar
          aria-hidden
          sx={{ width: 36, height: 36, fontSize: 14, fontWeight: 700, bgcolor: 'primary.main', color: 'primary.contrastText' }}
        >
          {hasName(contact) ? initialsOf(contact) : <Icon name="lucide:user" size={18} />}
        </Avatar>
      }
      footer={
        <Stack direction="row" justifyContent="flex-end">
          <Button variant="contained" onClick={onClose} sx={{ textTransform: 'none', fontWeight: 600 }}>
            Done
          </Button>
        </Stack>
      }
    >
      {user ? (
        <Stack spacing={2}>
          <Tabs
            variant="standard"
            value={active}
            onChange={(v) => selectTab(String(v) as UserPanelTab)}
            options={[
              { value: 'voicemail', label: newCount > 0 ? `Voicemail (${newCount})` : 'Voicemail', icon: 'lucide:voicemail' },
              { value: 'handling', label: 'Call handling', icon: 'lucide:phone-forwarded' },
              { value: 'history', label: 'Call history', icon: 'lucide:history' },
            ]}
          />
          {TABS.filter((t) => visited.includes(t)).map((t) => (
            <Box key={t} {...(t === 'voicemail' ? { [VOICEMAIL_ATTR]: '' } : {})} sx={{ display: active === t ? 'block' : 'none' }}>
              {renderTab(t)}
            </Box>
          ))}
        </Stack>
      ) : null}
    </SidePanel>
  );
}
