/**
 * "Queues for {agent}" (the Engage QueueManagementDialog): one agent against
 * every queue, with Member / Taking calls / Max calls per queue, a banner that
 * covers queues with callers waiting, and Take calls from all / Stop all.
 */
import { useEffect, useState } from 'react';

import type { QueueMember } from '../types';
import { useSwitchboard } from '../data/SwitchboardData';
import * as ns from '../api/ns';
import { agentId, memberLoggedIn } from '../model/agents';
import { describeError } from '../model/errors';
import { waitingCount } from '../model/queues';
import { useKit } from '../ui/kit';
import { Pill, SmallButton } from '../ui/bits';
import { MemberControls, RowError, useRowRunner } from './membership';
import { queueAgentCounts } from '../views/realtime/QueueTile';

/** Rosters older than this are re-read when the panel opens. */
const FRESH_MS = 15000;

export function AgentQueuesPanel({ user, onClose }: { user: string | null; onClose: () => void }) {
  const { SidePanel, Stack, Typography, Alert, Paper, Box, Button, Icon } = useKit();
  const sb = useSwitchboard();
  const { queues, contactsByUser, contacts, caps, domain, api, reloadRoster } = sb;
  const { pendingRow, bulk, busy, rowErrors, runRow, runBulk } = useRowRunner();
  const [bulkError, setBulkError] = useState<string | null>(null);
  const canManage = caps.manageQueueAgents;
  const contact = user ? contactsByUser.get(user) : undefined;
  const memberRow = (qExt: string): QueueMember | null =>
    queues.find((q) => q.ext === qExt)?.roster?.find((m) => m.user === user) ?? null;
  const agentName = contact?.name ?? queues.flatMap((q) => q.roster ?? []).find((m) => m.user === user)?.name ?? user ?? '';

  // Every roster must be current to show membership; refresh stale ones (3 at a time).
  useEffect(() => {
    if (!user) return;
    setBulkError(null);
    let alive = true;
    const stale = queues.filter((q) => !q.rosterLoadedAt || Date.now() - q.rosterLoadedAt > FRESH_MS).map((q) => q.ext);
    void (async () => {
      for (let i = 0; i < stale.length && alive; i += 3) {
        await Promise.all(stale.slice(i, i + 3).map((q) => reloadRoster(q)));
      }
    })();
    return () => {
      alive = false;
    };
    // Only when the panel opens for a user.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user]);

  const dnd = new Map(contacts.map((c) => [c.user, c.dnd] as const));
  const rows = queues.map((q) => {
    const m = memberRow(q.ext);
    return { q, m, loggedIn: m ? memberLoggedIn(m) : false, waiting: waitingCount(q), counts: queueAgentCounts(q, dnd) };
  });
  const loadedAll = queues.every((q) => q.roster !== null);
  const active = rows.filter((r) => r.m && r.loggedIn).length;
  const coverable = rows.filter((r) => r.waiting > 0 && !(r.m && r.loggedIn));
  const memberQueues = rows.filter((r) => r.m).map((r) => r.q.ext);

  const aid = user ? agentId(user, domain) : '';
  const afterOne = (q: string) => () => reloadRoster(q);
  const afterAll = async () => {
    for (const q of queues) await reloadRoster(q.ext);
  };

  const setMember = (q: string, on: boolean) =>
    runRow(q, () => (on ? ns.addAgent(api, domain, q, aid) : ns.removeAgent(api, domain, q, aid)), afterOne(q));
  const setTaking = (q: string, on: boolean) => runRow(q, () => ns.setTakingCalls(api, domain, q, aid, on), afterOne(q));
  const setMax = (q: string, n: number) => runRow(q, () => ns.setCallLimit(api, domain, q, aid, n), afterOne(q));

  const cover = () =>
    runBulk(
      coverable.map((r) => ({
        row: r.q.ext,
        fn: async () => {
          if (!r.m) await ns.addAgent(api, domain, r.q.ext, aid);
          await ns.setTakingCalls(api, domain, r.q.ext, aid, true);
        },
      })),
      afterAll,
    );

  const all = async (on: boolean) => {
    setBulkError(null);
    const targets = memberQueues;
    if (!targets.length) {
      setBulkError(`${agentName} is not a member of any queue yet.`);
      return;
    }
    let firstErr: unknown = null;
    const ok = await runBulk(
      targets.map((q) => ({
        row: q,
        fn: async () => {
          try {
            await ns.setTakingCalls(api, domain, q, aid, on);
          } catch (e) {
            firstErr = firstErr ?? e;
            throw e;
          }
        },
      })),
      afterAll,
    );
    if (ok === 0 && firstErr) {
      setBulkError(`${describeError(firstErr)} Nothing was changed. Try one queue at a time to see which is refusing.`);
    }
  };

  return (
    <SidePanel
      open={user !== null}
      onClose={onClose}
      title={`Queues for ${agentName}`}
      subtitle={user ? `Extension ${user}` : undefined}
      icon={<Icon name="lucide:users" size={20} />}
      width="lg"
      footer={
        <Stack direction="row" spacing={1} alignItems="center" sx={{ width: '100%' }}>
          <SmallButton
            icon="lucide:log-in"
            label="Take calls from all"
            disabled={!canManage || busy}
            onClick={() => void all(true)}
          />
          <SmallButton icon="lucide:log-out" label="Stop all" disabled={!canManage || busy} onClick={() => void all(false)} />
          <Box sx={{ flex: 1 }} />
          <Button variant="contained" onClick={onClose}>
            Done
          </Button>
        </Stack>
      }
    >
      <Stack spacing={2}>
        <Typography variant="body2" color="text.secondary">
          Taking calls from {active} of {queues.length} queue{queues.length === 1 ? '' : 's'}. Membership is the setup; the Taking calls
          switch is what you change during a spike.
        </Typography>
        {!canManage ? <Alert severity="info">Your scope can view queue membership but not change it.</Alert> : null}
        {bulkError ? <Alert severity="error">{bulkError}</Alert> : null}
        {canManage && coverable.length ? (
          <Alert severity="warning">
            <Stack direction="row" spacing={2} alignItems="center" justifyContent="space-between">
              <span>
                {coverable.length === 1
                  ? `${coverable[0].q.name} has callers waiting and ${agentName} is not covering it.`
                  : `${coverable.length} queues have callers waiting that ${agentName} is not covering.`}
              </span>
              <SmallButton
                icon="lucide:zap"
                label={coverable.length === 1 ? 'Cover it' : 'Cover them'}
                variant="contained"
                color="warning"
                busy={bulk}
                disabled={busy}
                onClick={() => void cover()}
              />
            </Stack>
          </Alert>
        ) : null}
        {!loadedAll ? (
          <Typography variant="caption" color="text.secondary">
            Loading queue rosters...
          </Typography>
        ) : null}
        <Stack spacing={1}>
          {rows.map(({ q, m, loggedIn, waiting, counts }) => (
            <Paper key={q.ext} variant="outlined" sx={{ p: 1.25 }}>
              <Stack direction="row" spacing={1} alignItems="center">
                <Box sx={{ flex: 1, minWidth: 0 }}>
                  <Typography variant="body2" sx={{ fontWeight: 700 }} noWrap>
                    {q.name}{' '}
                    <Box component="span" sx={{ color: 'text.secondary', fontWeight: 400 }}>
                      {q.ext}
                    </Box>
                  </Typography>
                  <Typography variant="caption" color="text.secondary">
                    {counts.available} of {counts.total} agents available
                  </Typography>
                  <RowError message={rowErrors[q.ext]} />
                </Box>
                {waiting > 0 ? <Pill tone="error" outlined label={`${waiting} waiting`} /> : null}
              </Stack>
              <Box sx={{ mt: 0.75 }}>
                <MemberControls
                  state={{ member: !!m, loggedIn, maxCalls: m?.callLimit }}
                  disabled={!canManage || busy || q.roster === null}
                  pending={pendingRow === q.ext}
                  names={{
                    member: `${m ? 'Remove' : 'Add'} ${agentName} ${m ? 'from' : 'to'} ${q.name}`,
                    taking: `${loggedIn ? 'Stop' : 'Start'} ${agentName} taking calls from ${q.name}`,
                    max: `Max simultaneous calls for ${agentName} from ${q.name}`,
                  }}
                  onMember={(on) => void setMember(q.ext, on)}
                  onTaking={(on) => void setTaking(q.ext, on)}
                  onMaxCalls={(n) => void setMax(q.ext, n)}
                />
              </Box>
            </Paper>
          ))}
        </Stack>
      </Stack>
    </SidePanel>
  );
}
